SP.MET_BY_CODE = SP.MET_RECORDS.reduce(function(acc, r){
  acc[r.c] = r; return acc;
}, {});

SP.metKcal = function(metValue, weightKg, minutes){
  if(!metValue || !weightKg || !minutes) return null;
  return Math.round(metValue * weightKg * (minutes / 60));
};
